n("ליזי", "ליזי היא צורת חיבה של אליזבת, שבא מהשם העברי אלישבע, אלי נשבע. באנגלית השם נפוץ גם כשם בפני עצמו, והוא מוכר מגיבורת הרומן גאווה ודעה קדומה. בארץ השם נדיר, והוא ניתן לבנות.", ["ליזה", "אלישבע"])
n("פביאן", "פביאן הוא שם בינלאומי ממקור לטיני, שבא משם של משפחה רומית עתיקה, פביוס, וקשור כנראה למילה פבה, שעועית. השם נפוץ בגרמנית, בצרפתית ובפולנית. בארץ הוא נדיר, והוא ניתן גם לבנים וגם לבנות.", [])
n("נינט", "נינט היא צורת חיבה צרפתית של אנה, שבאה מהשם העברי חנה, שפירושו חן. בצרפת השם היה נפוץ באמצע המאה העשרים. בארץ השם נדיר, והוא ניתן לבנות, והצליל שלו קליל ושמח.", ["אנה", "נינה"])
n("בשמת", "בשמת הוא שם מקראי מהמילה בושם, ריח טוב. בספר בראשית בשמת היא אחת מנשותיו של עשו, ובשמת הייתה גם בתו של שלמה המלך. השם ניתן לבנות, והוא נדיר. מוכר גם הכתיב בושמת.", ["בושמת"])
n("גלילה", "גלילה הוא שם עברי מהמילה גליל, האזור ההררי בצפון הארץ, וגם מהשורש ג־ל־ל, גלגול. השם היה נפוץ בארץ בשנות הארבעים והחמישים. גלילה ניתן לבנות, וקרובים אליו השמות גליל וגלית.", ["גליל", "גליה"])
n("אמנדה", "אמנדה הוא שם לטיני שפירושו ראויה לאהבה. השם נפוץ באנגלית ובשפות הצפון, והוא היה פופולרי באמריקה בשנות השמונים. בארץ השם נדיר, והוא ניתן לבנות.", [])
n("אודט", "אודט הוא שם צרפתי ממקור גרמני, שפירושו כנראה עושר. השם מוכר מהבלט אגם הברבורים, שבו אודט היא הנסיכה שהפכה לברבור. השם היה נפוץ בצרפת ובצפון אפריקה, והוא ניתן לבנות.", ["אודטה"])
n("עמיקם", "עמיקם הוא שם עברי חדש שבנוי מהמילים עמי וקם, ופירושו העם שלי קם. השם נולד בתקופה של התחייה הלאומית, והוא מביע תקווה. עמיקם הוא גם שם של מושב בצפון. השם ניתן לבנים, והוא נדיר.", ["עמי"])
n("זמיר", "זמיר הוא שם עברי מהמילה זמר, שיר, וגם שם של ציפור שיר. יש שקושרים אותו גם לעת הזמיר, עונת האביב. השם ניתן לבנים, והוא היה נפוץ בארץ בשנות החמישים. קרובה אליו צורת הנקבה זמירה.", ["זמירה"])
n("דונה", "דונה היא המילה האיטלקית לגברת, וגם צורה קצרה של שמות כמו מדונה. השם היה נפוץ באמריקה באמצע המאה העשרים. בארץ השם נדיר, והוא ניתן לבנות. בעברית הוא נשמע קרוב לדנה.", ["דנה"])
n("רחלה", "רחלה היא צורה של רחל, אחת מארבע האימהות. השם רחל פירושו כבשה. רחלה היה נפוץ בארץ בשנות הארבעים והחמישים, והוא ניתן לבנות. קרובים אליו השמות רחל ורחלי.", ["רחל", "רחלי"])
n("שירית", "שירית הוא שם עברי מהמילה שיר. מאותה מילה באים גם השמות שירה ושירן. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות. יש בו צליל מוזיקלי ורך.", ["שירה", "שיר"])
n("דרורית", "דרורית הוא שם עברי מהמילה דרור, חופש, וגם שמה של ציפור קטנה וחופשייה. השם היה נפוץ בארץ בשנות החמישים והשישים. דרורית ניתן לבנות, וקרובים אליו השמות דרור ודרורה.", ["דרור", "דרורה"])
n("עזר", "עזר הוא שם עברי מהמילה עזרה. מאותו שורש באים גם השמות עזרא, אליעזר ועזריאל. השם ניתן לבנים, והוא נדיר. הוא מוכר בארץ בזכות עזר ויצמן, נשיא המדינה השביעי.", ["עזרא", "אליעזר"])
n("גנית", "גנית הוא שם עברי מהמילה גן, מקום של עצים ופרחים. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות. קרובים אליו השמות גני וגינת.", ["גני", "גינת"])
n("בכור", "בכור הוא שם עברי מהמילה בכור, הבן הראשון במשפחה. השם היה נפוץ בעיקר בקהילות של יהודי בוכרה, פרס ותורכיה. השם ניתן לבנים, והוא נדיר היום. קרובה אליו צורת הנקבה בכורה.", ["בכורה"])
n("בקי", "בקי היא צורת חיבה של רבקה, ובאנגלית היא נכתבת בקי או בקה. השם רבקה בא מהשורש ר־ב־ק, קשר וחיבור. בארץ השם נדיר, והוא ניתן לבנות, והוא נשמע קליל.", ["רבקה"])
n("ליזט", "ליזט היא צורת חיבה צרפתית של אליזבת, שבאה מהשם העברי אלישבע. השם היה נפוץ בצרפת ובצפון אפריקה, והוא הגיע לארץ עם העלייה. השם ניתן לבנות, והוא נדיר.", ["ליזי", "אלישבע"])
n("סבסטיאן", "סבסטיאן הוא שם בינלאומי ממקור יווני, שפירושו נכבד או מכובד. השם נפוץ בשפה הספרדית, בגרמנית ובצרפתית. בארץ הוא נדיר, והוא ניתן לבנים.", [])
n("טירן", "טירן הוא שמו של אי בים סוף, ושל המצרים שבין סיני לערב הסעודית. המצרים האלה היו חשובים מאוד בהיסטוריה של המדינה. השם ניתן לבנים, והוא נדיר. מוכר גם הכתיב טיראן.", ["טיראן"])
n("פלורנס", "פלורנס הוא שם שבא מהמילה הלטינית פלורנס, פורחת. זה גם השם האנגלי של העיר פירנצה. השם מוכר בזכות פלורנס נייטינגייל, האחות שייסדה את הסיעוד המודרני. השם ניתן לבנות, והוא נדיר.", ["פלורה"])
n("נצחיה", "נצחיה הוא שם עברי שבנוי מהמילים נצח ויה, ופירושו הנצח של אלוהים. השם נשמע חגיגי ועמוק. השם ניתן לבנות, והוא נדיר. קרוב אליו השם נצח.", ["נצח"])
n("דיאגו", "דיאגו הוא שם ספרדי, וכנראה הוא בא מהשם סנטיאגו, שהוא צורה של יעקב. השם נפוץ בספרד ובאמריקה הלטינית. בארץ השם נדיר, והוא ניתן לבנים.", ["יעקב"])
n("מרגרט", "מרגרט הוא שם בינלאומי שבא מהמילה היוונית מרגריטס, פנינה. השם היה נפוץ מאוד באנגליה ובאירופה. מוכרות לו הרבה צורות, למשל מגי ומרגו. בארץ השם נדיר, והוא ניתן לבנות.", ["מגי", "פנינה"])
n("שושן", "שושן הוא שם של פרח לבן, וגם של עיר הבירה של פרס. במגילת אסתר שושן הבירה היא המקום שבו מתרחש כל הסיפור, ושם נחגג פורים ביום מאוחר יותר. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", ["שושנה", "ששון"])
n("פיבי", "פיבי הוא שם שבא מהמילה היוונית פויבה, זוהרת. במיתולוגיה היוונית פויבה היא אחת הטיטאניות. באנגלית השם נפוץ, והוא מוכר מסדרות טלוויזיה. בארץ השם נדיר, והוא ניתן לבנות.", [])
n("ריצרד", "ריצרד הוא כתיב של ריצ׳רד, שם בינלאומי ממקור גרמני שפירושו שליט חזק. בכתיב הזה השם נכתב בלי הגרש. השם ניתן לבנים, והוא נדיר בארץ.", ["ריצ'רד"])
n("דיצה", "דיצה הוא שם עברי מהמילה דיצה, שמחה גדולה. השם היה נפוץ בארץ בשנות הארבעים והחמישים, והוא ניתן לבנות. הוא קצר ושמח, וקרובים אליו שמות של שמחה כמו גילה ורינה.", ["גילה", "רינה"])
n("רנית", "רנית הוא שם עברי מהמילה רינה, שירה ושמחה. מאותו שורש באים גם השמות המוכרים רן, רוני ורינה. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות.", ["רינה", "רוני"])
n("ברנדה", "ברנדה הוא שם אנגלי ממקור נורדי, שקשור כנראה למילה חרב או אש. השם היה נפוץ באנגליה ובאמריקה באמצע המאה העשרים. בארץ השם נדיר, והוא ניתן לבנות.", [])
n("שנית", "שנית הוא שם עברי מהמילה שני, צבע אדום עמוק שהפיקו מתולעת. בעברית שנית היא גם המילה לפעם נוספת. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות שני ושונית.", ["שני", "שונית"])
n("הלית", "הלית הוא שם עברי חדש, וכנראה הוא בא מהמילה הילה, טבעת של אור. השם קרוב לשמות הילה והילית. השם ניתן לבנות, והוא נדיר. הצליל שלו רך ועדין.", ["הילה", "הילית"])
n("יהורם", "יהורם הוא שם מקראי שפירושו ה׳ רם. בספר מלכים יש שני מלכים בשם הזה, אחד ביהודה ואחד בישראל, שמלכו באותה תקופה. השם ניתן לבנים, והוא נדיר. קרוב אליו מאוד השם יורם.", ["יורם", "רם"])
n("קלייר", "קלייר היא הצורה הצרפתית של קלרה, שם לטיני שפירושו בהירה. השם נפוץ בצרפת ובאנגליה. בארץ השם נדיר, והוא ניתן לבנות. הוא נשמע בהיר ועדין.", ["קלרה"])
n("ויולט", "ויולט היא המילה האנגלית לסיגלית, הפרח הסגול. השם נפוץ באנגליה ובאמריקה, והוא חזר להיות אופנתי בשנים האחרונות. בארץ השם נדיר, והוא ניתן לבנות.", ["סיגלית", "ויולטה"])
n("לטיסיה", "לטיסיה הוא שם שבא מהמילה הלטינית לטיציה, שמחה. השם נפוץ בצרפת ובאיטליה. בארץ הוא נדיר, והוא ניתן לבנות. יש בו צליל עשיר ורך.", [])
n("חובב", "חובב הוא שם מקראי מהמילה חובב, אוהב. בספר במדבר חובב הוא חותנו של משה, ומשה מבקש ממנו ללכת עם העם במדבר. השם ניתן לבנים, והוא נדיר. נאות חובב היא גם שם של מקום בנגב.", [])
n("יפת", "יפת הוא אחד משלושת בני נח. בספר בראשית מסופר על שם, חם ויפת, ולפי המסורת מיפת באו העמים של אירופה. השם קשור כנראה למילה יופי. השם ניתן לבנים, והוא נפוץ בעיקר בקהילות של יהודי תימן.", ["יפה", "יפית"])
n("ג'ולייט", "ג׳ולייט היא צורה צרפתית ואנגלית של יוליה, שם לטיני עתיק. השם מוכר מהמחזה רומיאו ויוליה של שייקספיר. בארץ השם נדיר, והוא ניתן לבנות.", ["יוליה"])
n("אולה", "אולה הוא שם סלאבי, צורת חיבה של אלכסנדרה ושל אולגה. בפולנית השם נפוץ מאוד. בעברית השם נשמע גם קרוב לאולה, מלשון עלייה. השם ניתן לבנות, והוא נדיר בארץ.", ["אולגה"])
n("גרציה", "גרציה היא המילה האיטלקית לחן ולחסד. השם היה נפוץ בקהילות של יהודי איטליה, והוא מוכר בזכות דונה גרציה, אשת עסקים יהודייה שהצילה אנוסים בספרד ובפורטוגל. השם ניתן לבנות.", ["חן"])
n("תניה", "תניה הוא כתיב של טניה, צורת חיבה רוסית של טטיאנה. בעברית השם נשמע גם כמו תניא, ספר יסוד של חסידות חב״ד. השם ניתן לבנות, והוא נדיר.", ["תניא", "טניה"])
n("הדי", "הדי הוא שם עברי מהמילה הד, קול שחוזר מן ההרים. השם נשמע קצר ובהיר, והוא ניתן גם לבנים וגם לבנות. הוא נדיר, וקרובים אליו השמות הוד והודיה.", ["הוד", "הודיה"])
n("רימונה", "רימונה הוא שם עברי מהמילה רימון, הפרי האדום עם הגרגרים הרבים. הרימון הוא אחד משבעת המינים, והוא סמל של שפע ושל מצוות רבות. השם ניתן לבנות, והוא נדיר.", ["רימון"])
n("פנינית", "פנינית הוא שם עברי מהמילה פנינה, אבן יקרה ולבנה שנוצרת בתוך צדפה. השם קרוב לשם פנינה. הוא ניתן לבנות, והוא נדיר. יש בו תחושה של דבר יקר.", ["פנינה"])
n("מיגל", "מיגל הוא הצורה הספרדית של מיכאל, שם עברי שפירושו מי כמו אלוהים. השם נפוץ בספרד ובאמריקה הלטינית, והוא מוכר בזכות הסופר מיגל דה סרוונטס. בארץ השם נדיר, והוא ניתן לבנים.", ["מיכאל"])
n("ג'יימס", "ג׳יימס הוא הצורה האנגלית של יעקב, אחד משלושת האבות. השם נפוץ מאוד באנגליה ובאמריקה, והוא היה שמם של כמה מלכים. בארץ השם נדיר, והוא ניתן לבנים.", ["יעקב"])
n("שמוליק", "שמוליק היא צורת חיבה ביידיש של שמואל, שם שפירושו כנראה שמו אל או שאלתיו מאל. השם היה נפוץ מאוד בארץ בשנות הארבעים והחמישים. השם ניתן לבנים, והוא נשמע חם ומשפחתי.", ["שמואל"])
n("שקמה", "שקמה היא עץ גדול ורחב שגדל בשפלה ובמישור החוף, ונותן צל ופירות קטנים. השם עברי, והוא ניתן לבנות. שקמה היא גם שמו של נחל בדרום. מוכר גם הכתיב שיקמה.", ["שיקמה"])
n("קרנית", "קרנית הוא שם עברי מהמילה קרן, קרן אור. מאותה מילה באים גם השמות קרן וקרני. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות.", ["קרן", "קרני"])
n("ראומה", "ראומה הוא שם מקראי. בספר בראשית ראומה היא הפילגש של נחור, אחיו של אברהם. השם נשמע עתיק ומיוחד, והוא ניתן לבנות. ראומה הוא גם שם של יישוב בארץ, והוא נדיר.", [])
n("טלילה", "טלילה הוא שם עברי מהמילה טל, טיפות של לחות בבוקר. מאותה מילה באים גם השמות טל וטליה. השם היה נפוץ בארץ בשנות החמישים והשישים, והוא ניתן לבנות.", ["טל", "טליה"])
